const payload = $json.body || $json;
const event = payload.event || payload;
const resource = event.resource || {};
const rawEvent = event.raw?.event || {};
const actions = Array.isArray(rawEvent.action_list) ? rawEvent.action_list : [];

function parseMaybeJson(value) {
  if (typeof value !== 'string') return value;
  const text = value.trim();
  if (!text) return '';
  if (!['{', '['].includes(text[0])) return text;
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

function collectText(value) {
  const parsed = parseMaybeJson(value);
  if (parsed === null || parsed === undefined) return [];
  if (typeof parsed === 'string' || typeof parsed === 'number' || typeof parsed === 'boolean') {
    const text = String(parsed).trim();
    return text ? [text] : [];
  }
  if (Array.isArray(parsed)) {
    return parsed.flatMap(collectText).filter(Boolean);
  }
  if (typeof parsed === 'object') {
    if (Array.isArray(parsed.users)) {
      return parsed.users.flatMap(user => collectText(user?.name || user?.enName || user?.userId));
    }
    if (Array.isArray(parsed.data)) {
      return parsed.data.flatMap(collectText).filter(Boolean);
    }
    if (parsed.text !== undefined) return collectText(parsed.text);
    if (parsed.name !== undefined) return collectText(parsed.name);
    if (parsed.value !== undefined) return collectText(parsed.value);
  }
  return [];
}

function unique(values) {
  return [...new Set(values.map(value => String(value).trim()).filter(Boolean))];
}

function fieldText(fieldId) {
  const values = [];
  for (const action of actions) {
    const afterValues = Array.isArray(action.after_value) ? action.after_value : [];
    for (const field of afterValues) {
      if (String(field.field_id || '') !== fieldId) continue;
      values.push(...collectText(field.field_identity_value));
      values.push(...collectText(field.field_value));
    }
  }
  return unique(values).join('；');
}

const result = {
  record_id: resource.record_id || '',
  table_id: resource.table_id || '',
  客户需求: fieldText('fldsuKm8jW'),
  联系人: fieldText('fld1QdGtzJ'),
  联系方式: fieldText('fld3d5yFvP'),
  单位: fieldText('fldG4YOiIT'),
  策划师: fieldText('fld6UQO969'),
};

result.code = [
  '报价基础数据',
  `客户需求：${result.客户需求}`,
  `联系人：${result.联系人}`,
  `联系方式：${result.联系方式}`,
  `单位：${result.单位}`,
  `策划师：${result.策划师}`,
].join('\n');

return [{ json: result }];
